mapper.update:
UPDATE task_instance
SET lease_until = TIMESTAMPADD(
        SECOND,
        #{leaseSeconds},
        UTC_TIMESTAMP(3)
    )
WHERE id = #{instanceId}
  AND status = 'RUNNING'
  AND lease_owner = #{workerId}
  AND lease_version = #{leaseVersion}
  AND lease_until > UTC_TIMESTAMP(3)

UPDATE task_instance
SET status = 'SUCCESS',
    lease_owner = NULL,
    lease_until = NULL
WHERE id = #{instanceId}
  AND status = 'RUNNING'
  AND lease_owner = #{workerId}
  AND lease_version = #{leaseVersion}
  AND lease_until > UTC_TIMESTAMP(3)

UPDATE task_instance
SET status = 'FAILED', lease_owner = NULL, lease_until = NULL
WHERE id = #{instanceId}
  AND status = 'RUNNING'
  AND lease_owner = #{workerId}
  AND lease_version = #{leaseVersion}
  AND lease_until > UTC_TIMESTAMP(3)
